var tex=Path.Combine(root,"a.png");File.WriteAllBytes(tex,[1,2,3,4]);var relative=d.Import(tex,false);Check(File.ReadAllBytes(Paths.Resolve(root,relative)).SequenceEqual(File.ReadAllBytes(tex)),"import exact bytes");Check(d.Import(tex,false)==relative,"content deduplicated");
File.AppendAllText(gp," ");Reject(()=>d.Save((_,_)=>{}),"external edit refused");Reject(()=>Document.Open(tex),"invalid document refused");
