iconDocument.Save((_,_)=>{});Check(Document.Open(iconGameplay).Weapon(25)["visual"]?["iconPath"]?.GetValue<string>()==iconRelative,"icon saved and reopened");Check(File.ReadAllText(Path.Combine(iconRoot,"assets.sha256")).Contains(Document.Hash(Paths.Resolve(iconRoot,iconRelative))+"  "+iconRelative),"icon asset hash tracked");
