File.WriteAllText(Path.Combine(iconRoot,"weapon-icons/index.tsv"),"MGO2MT_WEAPON_ICONS\t1\nICON\t25\tak.png\n");Check(WeaponIcons.Resolve(iconDocument,25)=="weapon-icons/ak.png","renamed original icon index supported");
